import 'package:flutter/material.dart';import 'package:firebase_auth/firebase_auth.dart';import '../../../services/personal_ai/routine_service.dart';
class AurenRoutineScreen extends StatefulWidget{const AurenRoutineScreen({super.key});@override State<AurenRoutineScreen> createState()=>_S();}
class _S extends State<AurenRoutineScreen>{final n=TextEditingController();final s=RoutineService();@override void dispose(){n.dispose();super.dispose();}@override Widget build(BuildContext c){final u=FirebaseAuth.instance.currentUser?.uid;if(u==null)return const Scaffold(body:Center(child:Text('يجب تسجيل الدخول')));return Scaffold(appBar:AppBar(title:const Text('Routine')),body:StreamBuilder<List<AurenRoutine>>(stream:s.watch(u),builder:(c,x){final a=x.data??const[];return ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:n,decoration:const InputDecoration(labelText:'اسم الروتين',prefixIcon:Icon(Icons.repeat))),const SizedBox(height:8),FilledButton.icon(onPressed:()async{if(n.text.trim().isNotEmpty){await s.create(u,n.text,'08:00');n.clear();}},icon:const Icon(Icons.add),label:const Text('إضافة')),const SizedBox(height:12),...a.map((r)=>Card(child:ListTile(title:Text(r.name),subtitle:Text('يومياً • ${r.time}'),leading:Icon(r.active?Icons.check_circle:Icons.pause_circle),onTap:()=>s.toggle(u,r),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>s.delete(u,r.id)))))]); }));}}